-- Ghāfir 40:6 — «وَكَذَلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى الَّذِينَ كَفَرُوا أَنَّهُمْ أَصْحَابُ النَّارِ» — the whole of passage 3, built in
-- one cycle (km-cyb-ss-build-sentence; drill-engine plan Phase 3.4): the classical tree, every iʿrāb book (three parse,
-- al-ʿUkbarī defers to Yūnus 10:33, al-Darwīsh and the dependency graphs are silent), seven tafsīrs (al-Rāzī, al-Zamakhsharī,
-- al-Ālūsī, Ibn ʿĀshūr, al-Ṭabarī, Ibn ʿAṭiyya, Ibn Kathīr), and the derived translation. The two readings of «أنهم أصحاب
-- النار» — بدل from «كلمة ربك» (the majority) and منصوب بنزع الخافض «لأنهم» (al-Ālūsī's preference) — are kept apart.

UPDATE qr_ss_occ_sentence SET gt_sentence_class = 'GT:sentence_class:filiyya', gt_kalam_kind = 'GT:kalam_kind:khabar_ibtidai',
       gt_sentence_role = 'GT:sentence_role:istinafiyya', discourse_role = 'tashbih_tadhyil',
       gloss_json = '{"ar": "جملة فعلية استئنافية لا محل لها: «كذلك» صفة لمصدر محذوف، و«كلمة ربك» فاعل، و«أنهم أصحاب النار» بدل منها أو على تقدير لام التعليل.", "en": "A resumptive verbal sentence with no grammatical place: «kadhālika» qualifies an omitted cognate object, «the word of your Lord» is the agent, and «that they are the people of the Fire» stands in for that word — or gives its cause, with the لام dropped.", "ur": "ایک مستانفہ فعلیہ جملہ جس کا اعرابی محل نہیں: «کذلک» محذوف مصدر کی صفت ہے، «کلمۃ ربک» فاعل ہے، اور «انہم اصحاب النار» اس کلمے کا بدل ہے — یا لامِ تعلیل محذوف کے ساتھ اس کی علت۔"}',
       source_basis = 'QR:EV:40:6:jadwal:1;QR:EV:40:6:daas:1;QR:EV:40:6:muyassar:1'
 WHERE id = 'QR:SS:40:6:jadwal:s1';

INSERT OR REPLACE INTO qr_ss_occ_clause (id, sentence_id, parent_clause_id, clause_order, surah, ayah_from, ayah_to, word_start_index, word_end_index, clause_type, clause_function, governing_particle, is_virtual, source_basis, gloss_json) VALUES
('QR:CL:40:6:c1', 'QR:SS:40:6:jadwal:s1', NULL, 1, 40, 6, 6, 1, 10, 'main', 'istinafiyya', NULL, 0, 'QR:EV:40:6:jadwal:1', '{"ar": "الجملة الفعلية «حقّت كلمة ربك…» استئنافية لا محل لها (الجدول).", "en": "The verbal clause «the word of your Lord came due…», resumptive, with no grammatical place (al-Jadwal).", "ur": "فعلیہ جملہ «حقت کلمۃ ربک…» مستانفہ، اعرابی محل سے خالی (الجدول)۔"}'),
('QR:CL:40:6:c2', 'QR:SS:40:6:jadwal:s1', 'QR:CL:40:6:c1', 2, 40, 6, 6, 7, 7, 'subordinate', 'silat_mawsul', 'الذين', 0, 'QR:EV:40:6:jadwal:1', '{"ar": "«كفروا» صلة الموصول «الذين» لا محل لها (الجدول ودعاس).", "en": "«kafarū» is the relative clause of «alladhīna», with no place (al-Jadwal, al-Daʿʿās).", "ur": "«کفروا» موصول «الذین» کا صلہ ہے، جس کا محل نہیں (الجدول، دعاس)۔"}'),
('QR:CL:40:6:c3', 'QR:SS:40:6:jadwal:s1', 'QR:CL:40:6:c1', 3, 40, 6, 6, 8, 10, 'subordinate', 'badal', 'أنّ', 0, 'QR:EV:40:6:daas:1;QR:EV:40:6:muyassar:1', '{"ar": "«أنّهم أصحاب النار» مصدر مؤول بدل من «كلمة ربك» (دعاس والميسر)، أو منصوب بنزع الخافض (الميسر وجهًا ثانيًا).", "en": "«that they are the people of the Fire» — an interpreted verbal noun standing in for «the word of your Lord» (al-Daʿʿās, al-Muyassar), or accusative with the preposition dropped (al-Muyassar''s second reading).", "ur": "«انہم اصحاب النار» مصدرِ مؤول ہے جو «کلمۃ ربک» کا بدل ہے (دعاس، المیسر)، یا حرفِ جر کے حذف سے منصوب (المیسر کا دوسرا قول)۔"}');

