('QR:SML:40:6:8', 'word', '1df635c70dffbecaa89fa7e27c', 'GT:irab_role:ism_inna', 'mabni', 'fath', 'harf_nasikh_wa_ismuha', 'GT:irab_role:ism_inna', 1, 'المصدر المؤول بدل في محل رفع، أو في محل نصب بنزع الخافض', '2026-10-15 16:00:00'),
