INSERT OR REPLACE INTO qr_evidence (id, evidence_type, provenance, locator, source_ref, content_text_ar, content_text, is_disputed, created_at, updated_at) VALUES
('QR:EV:40:6:jadwal:1', 'irab_quote', 'الجدول في إعراب القرآن', '40:6', 'qul_jadwal_irab_quran', '(الواو) استئنافيّة (كذلك) متعلّق بمحذوف مطلق عامله حقّت (على الذين) متعلّق ب (حقّت). «حقّت كلمة ...» لا محلّ لها استئنافيّة. «كفروا ...» لا محلّ لها صلة الموصول (الذين).', 'The wāw resumes; «kadhālika» attaches to an omitted cognate object governed by «ḥaqqat»; «ʿalā lladhīna» attaches to «ḥaqqat». The sentence is resumptive with no place; «kafarū» is the relative clause.', 0, '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:EV:40:6:daas:1', 'irab_quote', 'إعراب القرآن لدعاس', '40:6', 'qul_irab_quran_daas', 'الواو حرف استئناف والكاف صفة لمفعول مطلق محذوف أو خبر لمبتدأ محذوف تقديره والأمر كذلك ... والمصدر المؤول من أن وما بعدها بدل من كلمة', 'The wāw resumes; the kāf qualifies an omitted cognate object, or is the predicate of an omitted subject («the matter is like that»). The verbal noun from «anna» and its clause substitutes for «kalima».', 0, '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:EV:40:6:muyassar:1', 'irab_quote', 'الإعراب الميسر', '40:6', 'qul_irab_muyassar', 'الكاف اسم بمعنى مثل مبني على الفتح في محل نصب صفة لمصدر محذوف مقدم على عامله، أو في محل رفع خبر لمبتدأ محذوف، أي: والأمر مثل ذلك ... والمصدر المؤول من ﴿أنهم أصحاب النار﴾ بدل مرفوع من ﴿كلمة ربك﴾، أو منصوب بنزع الخافض، وهو لام التعليل.', 'The kāf, a noun meaning «like», qualifies an omitted cognate object fronted before its governor, or is the predicate of an omitted subject. The verbal noun «that they are the people of the Fire» is a nominative substitute for «the word of your Lord», or accusative with the preposition — the لام of cause — dropped.', 0, '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:EV:40:6:ukbari:1', 'irab_quote', 'التبيان في إعراب القرآن', '40:6', 'tibyan_ukbari_irab', '(أنهم) : هو مثل الذي في يونس.', '«annahum»: like the one in Yūnus — the book defers to its treatment of 10:33.', 0, '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:EV:10:33:ukbari:1', 'irab_quote', 'التبيان في إعراب القرآن', '10:33', 'tibyan_ukbari_irab', '(أنهم لا يؤمنون) : أن وما عملت فيه - في موضع رفع بدلا من «كلمة» . أو خبر مبتدأ محذوف. أو في موضع نصب ; أي لأنهم. أو في موضع جر على إعمال اللام محذوفة.', 'At Yūnus 10:33: «anna» with its clause is nominative as a substitute for «kalima», or the predicate of an omitted subject, or accusative («because they…»), or genitive with the dropped لام still governing.', 0, '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:EV:40:6:zamakhshari:1', 'tafsir_quote', 'الكشاف', '40:6', 'zamakhshari', 'أَنَّهُمْ أَصْحابُ النَّارِ في محل الرفع بدل من كَلِمَةُ رَبِّكَ ... أو في محل النصب بحذف لام التعليل وإيصال الفعل. والذين كفروا: قريش', '«annahum aṣḥābu n-nār» is nominative, a substitute for «kalimatu rabbika» — or accusative, the لام of cause dropped and the verb reaching it directly. «Those who disbelieved» are Quraysh.', 0, '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:EV:40:6:alusi:1', 'tafsir_quote', 'روح المعاني', '40:6', 'alusi', '﴿أنهم أصحاب النار﴾ أي لأنهم أصحاب النار ... في حيز النصب بحذف لام التعليل ... وجوز أن يكون في محل رفع على أنه بدل من ﴿كلمة ربك﴾ ... والوجه الأول أظهر بالمساق', '«annahum…» means «because they are the people of the Fire», accusative with the لام of cause dropped; being a substitute for «kalimatu rabbika» is allowed — but the first reading fits the context better.', 0, '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:EV:40:6:ibn_ashur:1', 'tafsir_quote', 'التحرير والتنوير', '40:6', 'ibn_ashur', 'الواو عاطفة على جملة ﴿فكيف كان عقاب﴾ ... وقوله ﴿أنهم أصحاب النار﴾ يجوز أن يكون بدلا من (كلمات ربك) بدلا مطابقا ... ويجوز أن يكون على تقدير لام التعليل محذوفة على طريقة كثرة حذفها قبل أن', 'The wāw joins this to «so how was My punishment?» (40:5). «annahum…» may be an exact substitute for «the words of your Lord», or may carry an omitted لام of cause, as is common before «anna».', 0, '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:EV:40:6:ibn_ashur:2', 'tafsir_quote', 'التحرير والتنوير', '40:6', 'ibn_ashur', 'فالمراد بـ (الذين كفروا) جميع الكافرين، فالكلام تعميم بعد تخصيص فهو تذييل ... وبذلك يكون التشبيه في قوله «وكذلك حقت كلمات ربك» جاريا على أصل التشبيه من المغايرة بين المشبه والمشبه به', '«Those who disbelieved» are all disbelievers, so the statement generalises after the particular — a closing summary (tadhyīl); the simile «just so» then compares two different things, as a simile normally does.', 0, '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:EV:40:6:tabari:1', 'tafsir_quote', 'جامع البيان', '40:6', 'tabari', 'والصواب من القول في ذلك، أن قوله"أنهم" ترجمة عن الكلمة، بمعنى: وكذلك حقّ عليهم عذاب النار، الذي وعد الله أهل الكفر به.', 'The right view is that «annahum» renders (substitutes for) the word: just so the punishment of the Fire that God promised the disbelievers came due upon them.', 0, '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:EV:40:6:ibn_atiyya:1', 'tafsir_quote', 'المحرر الوجيز', '40:6', 'ibn_atiyya', 'كما أخذت أولئك المذكورين فأهلكتهم فكذلك حقت كلماتي على جميع الكفار، من تقدم منهم ومن تأخر، أنهم أهل النار وسكانها ... وقوله: ﴿أنهم﴾ بدل من "كلمة".', 'As I seized and destroyed those mentioned, just so My words came due on all disbelievers, earlier and later — that they are the people and dwellers of the Fire. «annahum» substitutes for «kalima».', 0, '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:EV:40:6:razi:1', 'tafsir_quote', 'مفاتيح الغيب', '40:6', 'razi', 'أي ومثل الذي حق على أولئك الأمم السالفة من العقاب حقت كلمتي أيضا على هؤلاء الذين كفروا من قومك، فهم على شرف نزول العقاب بهم', 'As punishment came due upon those earlier nations, My word has come due upon these disbelievers of your people too: they stand on the verge of its falling on them.', 0, '2026-10-15 16:00:00', '2026-10-15 16:00:00');

INSERT OR REPLACE INTO qr_ss_scope_reading (id, scope_type, scope_id, scholar_ref, paradigm_ref, reading_type, reading_text, reading_text_ar, is_minority, is_contested, is_selected, witness_count, note_md, gloss_json, created_at, updated_at) VALUES
('QR:SR:40:6:r1', 'sentence', 'QR:SS:40:6:jadwal:s1', 'qul_jadwal_irab_quran;qul_irab_quran_daas', 'jumhur', 'irab', 'A resumptive sentence with no grammatical place; the wāw resumes.', 'الجملة استئنافية لا محل لها من الإعراب، والواو حرف استئناف.', 0, 0, 1, 2, NULL, '{"ar": "الجملة استئنافية لا محل لها من الإعراب، والواو حرف استئناف.", "en": "A resumptive sentence with no grammatical place; the wāw resumes.", "ur": "یہ جملہ مستانفہ ہے، اعرابی محل سے خالی؛ واؤ استیناف کی ہے۔"}', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:SR:40:6:r2', 'sentence', 'QR:SS:40:6:jadwal:s1', 'ibn_ashur', 'minority', 'irab', 'Ibn ʿĀshūr: the wāw joins this to «so how was My punishment?»; both have no place.', 'ابن عاشور: الواو عاطفة على جملة «فكيف كان عقاب»، والجملتان لا محل لهما.', 1, 1, 0, 1, NULL, '{"ar": "ابن عاشور: الواو عاطفة على جملة «فكيف كان عقاب»، والجملتان لا محل لهما.", "en": "Ibn ʿĀshūr: the wāw joins this to «so how was My punishment?»; both have no place.", "ur": "ابن عاشور: واؤ عاطفہ ہے جو اسے «فکیف کان عقاب» پر عطف کرتی ہے؛ دونوں جملوں کا محل نہیں۔"}', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:SR:40:6:r3', 'phrase', 'QR:PH:40:6:p1', 'qul_jadwal_irab_quran;qul_irab_quran_daas;qul_irab_muyassar', 'jumhur', 'irab', '«kadhālika»: the kāf qualifies an omitted cognate object fronted before its governor — «came due with a coming-due like that».', '«كذلك»: الكاف صفة لمصدر محذوف مقدّم على عامله، تقديره: حقّت حقًّا مثلَ ذلك.', 0, 0, 1, 3, NULL, '{"ar": "«كذلك»: الكاف صفة لمصدر محذوف مقدّم على عامله، تقديره: حقّت حقًّا مثلَ ذلك.", "en": "«kadhālika»: the kāf qualifies an omitted cognate object fronted before its governor — «came due with a coming-due like that».", "ur": "«کذلک»: کاف ایک محذوف مفعولِ مطلق کی صفت ہے جو اپنے عامل سے پہلے آئی — یعنی «ویسا ہی ثابت ہونا ثابت ہوا»۔"}', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:SR:40:6:r4', 'phrase', 'QR:PH:40:6:p1', 'qul_irab_quran_daas;qul_irab_muyassar', 'minority', 'irab', '«kadhālika» is the predicate of an omitted subject: «and the matter is like that».', '«كذلك» خبر لمبتدأ محذوف تقديره: والأمرُ كذلك.', 1, 0, 0, 2, NULL, '{"ar": "«كذلك» خبر لمبتدأ محذوف تقديره: والأمرُ كذلك.", "en": "«kadhālika» is the predicate of an omitted subject: «and the matter is like that».", "ur": "«کذلک» ایک محذوف مبتدا کی خبر ہے: «اور معاملہ ایسا ہی ہے»۔"}', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:SR:40:6:r5', 'phrase', 'QR:PH:40:6:p4', 'qul_irab_quran_daas;qul_irab_muyassar;tibyan_ukbari_irab;zamakhshari;ibn_atiyya;tabari;ibn_ashur', 'jumhur', 'irab', '«that they are the people of the Fire» is an interpreted verbal noun, nominative, a substitute for «the word of your Lord».', '«أنهم أصحاب النار» مصدر مؤول في محل رفع بدل من «كلمة ربك».', 0, 0, 1, 7, 'al-Ṭabarī names it «tarjama» (a rendering of the word), the Kūfan term for badal; Ibn ʿĀshūr calls it an exact substitute; al-Ālūsī: total if the word is God''s judgment, inclusive (ishtimāl) if the word is wider.', '{"ar": "«أنهم أصحاب النار» مصدر مؤول في محل رفع بدل من «كلمة ربك».", "en": "«that they are the people of the Fire» is an interpreted verbal noun, nominative, a substitute for «the word of your Lord».", "ur": "«انہم اصحاب النار» مصدرِ مؤول ہے، محلاً مرفوع، «کلمۃ ربک» کا بدل۔"}', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:SR:40:6:r6', 'phrase', 'QR:PH:40:6:p4', 'alusi;qul_irab_muyassar;zamakhshari;ibn_ashur;tibyan_ukbari_irab', 'minority', 'irab', '«that they are the people of the Fire» is accusative with the لام of cause dropped: «because they are the people of the Fire».', '«أنهم أصحاب النار» في محل نصب بنزع الخافض على تقدير لام التعليل: لأنّهم أصحاب النار.', 1, 1, 0, 5, 'al-Ālūsī prefers it «by the run of the passage»; al-Muyassar, al-Zamakhsharī and Ibn ʿĀshūr give it second; al-ʿUkbarī lists it at Yūnus 10:33. Rule: dropping the preposition before «anna» (Ibn Hishām, Mughnī p.15).', '{"ar": "«أنهم أصحاب النار» في محل نصب بنزع الخافض على تقدير لام التعليل: لأنّهم أصحاب النار.", "en": "«that they are the people of the Fire» is accusative with the لام of cause dropped: «because they are the people of the Fire».", "ur": "«انہم اصحاب النار» حرفِ جر (لامِ تعلیل) کے حذف سے منصوب ہے: «کیونکہ وہ اہلِ دوزخ ہیں»۔"}', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:SR:40:6:r7', 'sentence', 'QR:SS:40:6:jadwal:s1', 'tibyan_ukbari_irab', 'deferral', 'irab', 'Al-ʿUkbarī defers to Yūnus 10:33 («like the one in Yūnus»), where he gives four readings: substitute, predicate of an omitted subject, accusative with the لام understood, genitive with it still governing.', 'العكبري يحيل على نظيرها في يونس [١٠: ٣٣]: «هو مثل الذي في يونس»، وهناك أربعة أوجه: بدل، أو خبر لمبتدأ محذوف، أو نصب بتقدير اللام، أو جر بإعمالها محذوفة.', 0, 0, 0, 1, NULL, '{"ar": "العكبري يحيل على نظيرها في يونس [١٠: ٣٣]: «هو مثل الذي في يونس»، وهناك أربعة أوجه: بدل، أو خبر لمبتدأ محذوف، أو نصب بتقدير اللام، أو جر بإعمالها محذوفة.", "en": "Al-ʿUkbarī defers to Yūnus 10:33 («like the one in Yūnus»), where he gives four readings: substitute, predicate of an omitted subject, accusative with the لام understood, genitive with it still governing.", "ur": "عکبری یونس [۱۰: ۳۳] کی نظیر کا حوالہ دیتے ہیں، جہاں چار وجوہ ہیں: بدل، محذوف مبتدا کی خبر، لام مقدر کے ساتھ نصب، یا محذوف لام کے عمل سے جر۔"}', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:SR:40:6:census', 'sentence', 'QR:SS:40:6:jadwal:s1', 'qul_jadwal_irab_quran;qul_irab_quran_daas;qul_irab_muyassar;tibyan_ukbari_irab;qul_irab_darwish;qul_dep_graphs', 'synthesis', 'irab', 'Census of the six registered iʿrāb sources: three parse the verse (al-Jadwal, al-Daʿʿās, al-Muyassar), one defers (al-ʿUkbarī, to Yūnus 10:33), two are silent (al-Darwīsh, whose grouped 40:1–6 entry stops at 40:5; the dependency graphs, with no row for 40:6).', 'حصر كتب الإعراب الستة المسجلة: ثلاثة تعرب الآية (الجدول، دعاس، الميسر)، وواحد يحيل (العكبري إلى يونس ١٠: ٣٣)، واثنان ساكتان (الدرويش، إذ يقف إعرابه المجمّع ٤٠: ١–٦ عند الآية الخامسة؛ والمخططات الاعتمادية، لا صف لها في ٤٠: ٦).', 0, 0, 0, 3, NULL, '{"ar": "حصر كتب الإعراب الستة المسجلة: ثلاثة تعرب الآية (الجدول، دعاس، الميسر)، وواحد يحيل (العكبري إلى يونس ١٠: ٣٣)، واثنان ساكتان (الدرويش، إذ يقف إعرابه المجمّع ٤٠: ١–٦ عند الآية الخامسة؛ والمخططات الاعتمادية، لا صف لها في ٤٠: ٦).", "en": "Census of the six registered iʿrāb sources: three parse the verse (al-Jadwal, al-Daʿʿās, al-Muyassar), one defers (al-ʿUkbarī, to Yūnus 10:33), two are silent (al-Darwīsh, whose grouped 40:1–6 entry stops at 40:5; the dependency graphs, with no row for 40:6).", "ur": "چھ رجسٹرڈ اعرابی مصادر کا جائزہ: تین آیت کا اعراب کرتے ہیں (الجدول، دعاس، المیسر)، ایک حوالہ دیتا ہے (عکبری، یونس ۱۰: ۳۳)، دو خاموش ہیں (درویش، جن کا ۴۰: ۱–۶ کا مجموعی اعراب آیت ۵ پر رک جاتا ہے؛ اور dependency graphs، جن میں ۴۰: ۶ کی کوئی سطر نہیں)۔"}', '2026-10-15 16:00:00', '2026-10-15 16:00:00');

