INSERT OR REPLACE INTO qr_ss_scope_grammar_link (id, scope_type, scope_id, lx_grammar_ref, application_note, gloss_json, created_at) VALUES
('QR:GR:40:6:g1', 'sentence', 'QR:SS:40:6:jadwal:s1', 'GT:sentence_role:istinafiyya', 'The sentence resumes: no grammatical place (al-Jadwal; Mughnī p.500).', '{"ar": "الجملة مستأنفة لا محل لها (الجدول؛ مغني اللبيب ص٥٠٠).", "en": "The sentence resumes: no grammatical place (al-Jadwal; Mughnī p.500).", "ur": "جملہ مستانفہ ہے، محل سے خالی (الجدول؛ مغنی اللبیب ص۵۰۰)۔"}', '2026-10-15 16:00:00'),
('QR:GR:40:6:g2', 'phrase', 'QR:PH:40:6:p1', 'GT:irab_role:maful_mutlaq', 'An omitted cognate object («ḥaqqan»), qualified by the fronted «kadhālika».', '{"ar": "مصدر محذوف «حقًّا» مفعول مطلق، صفته «كذلك» المقدّمة.", "en": "An omitted cognate object («ḥaqqan»), qualified by the fronted «kadhālika».", "ur": "محذوف مصدر «حقاً» مفعولِ مطلق ہے، جس کی صفت مقدم «کذلک» ہے۔"}', '2026-10-15 16:00:00'),
('QR:GR:40:6:g3', 'phrase', 'QR:PH:40:6:p2', 'GT:irab_role:fail', '«kalimatu rabbika» is the agent of «ḥaqqat».', '{"ar": "«كلمة ربك» فاعل «حقّت».", "en": "«kalimatu rabbika» is the agent of «ḥaqqat».", "ur": "«کلمۃ ربک» «حقت» کا فاعل ہے۔"}', '2026-10-15 16:00:00'),
('QR:GR:40:6:g4', 'phrase', 'QR:PH:40:6:p3', 'GT:irab_role:mutaalliq', '«ʿalā lladhīna kafarū» attaches to the verb «ḥaqqat».', '{"ar": "«على الذين كفروا» متعلقان بالفعل «حقّت».", "en": "«ʿalā lladhīna kafarū» attaches to the verb «ḥaqqat».", "ur": "«علی الذین کفروا» فعل «حقت» سے متعلق ہے۔"}', '2026-10-15 16:00:00'),
('QR:GR:40:6:g5', 'clause', 'QR:CL:40:6:c2', 'GT:irab_role:silat_mawsul', '«kafarū» is the relative clause of «alladhīna», with no place.', '{"ar": "«كفروا» صلة الموصول لا محل لها.", "en": "«kafarū» is the relative clause of «alladhīna», with no place.", "ur": "«کفروا» صلۂ موصول ہے، محل سے خالی۔"}', '2026-10-15 16:00:00'),
('QR:GR:40:6:g6', 'phrase', 'QR:PH:40:6:p4', 'GT:irab_role:masdar_muawwal', '«anna» with its noun and predicate reads as a verbal noun (Mughnī p.60).', '{"ar": "«أنّ» ومعمولاها مؤوّلة بمصدر (مغني اللبيب ص٦٠).", "en": "«anna» with its noun and predicate reads as a verbal noun (Mughnī p.60).", "ur": "«انّ» اپنے دونوں معمولوں کے ساتھ مصدر کی تاویل میں ہے (مغنی اللبیب ص۶۰)۔"}', '2026-10-15 16:00:00'),
('QR:GR:40:6:g7', 'phrase', 'QR:PH:40:6:p4', 'GT:irab_role:badal', 'The verbal noun substitutes for «kalimatu rabbika» (the majority reading).', '{"ar": "المصدر المؤول بدل من «كلمة ربك» (قول الجمهور).", "en": "The verbal noun substitutes for «kalimatu rabbika» (the majority reading).", "ur": "مصدرِ مؤول «کلمۃ ربک» کا بدل ہے (جمہور کا قول)۔"}', '2026-10-15 16:00:00'),
('QR:GR:40:6:g8', 'phrase', 'QR:PH:40:6:p4', 'GT:irab_role:nazu_khafid', 'On the minority reading the لام of cause is dropped before «anna» and the clause is accusative (Mughnī p.15).', '{"ar": "على القول الثاني حُذفت لام التعليل قبل «أنّ» فالمصدر في محل نصب (مغني اللبيب ص١٥).", "en": "On the minority reading the لام of cause is dropped before «anna» and the clause is accusative (Mughnī p.15).", "ur": "دوسرے قول پر «انّ» سے پہلے لامِ تعلیل محذوف ہے اور مصدر محلاً منصوب ہے (مغنی اللبیب ص۱۵)۔"}', '2026-10-15 16:00:00'),
('QR:GR:40:6:g9', 'phrase', 'QR:PH:40:6:p4', 'GT:nawasikh:inna_wa_akhawatuha', '«anna» governs «hum» as its noun and «aṣḥābu n-nār» as its predicate (Mughnī p.59).', '{"ar": "«أنّ» تنصب «هم» اسمًا وترفع «أصحاب النار» خبرًا (مغني اللبيب ص٥٩).", "en": "«anna» governs «hum» as its noun and «aṣḥābu n-nār» as its predicate (Mughnī p.59).", "ur": "«انّ» «ہم» کو اسم بنا کر نصب اور «اصحاب النار» کو خبر بنا کر رفع دیتا ہے (مغنی اللبیب ص۵۹)۔"}', '2026-10-15 16:00:00'),
('QR:GR:40:6:g10', 'phrase', 'QR:PH:40:6:p5', 'GT:irab_role:mudaf_ilayh', '«an-nār» is the genitive annex of «aṣḥāb».', '{"ar": "«النار» مضاف إليه لـ«أصحاب».", "en": "«an-nār» is the genitive annex of «aṣḥāb».", "ur": "«النار» «اصحاب» کا مضاف الیہ ہے۔"}', '2026-10-15 16:00:00');

INSERT OR REPLACE INTO qr_ss_scope_balagha_link (id, scope_type, scope_id, lx_balagha_ref, balagha_category, rhetorical_effect, note_md, gloss_json, created_at) VALUES
('QR:BL:40:6:b1', 'phrase', 'QR:PH:40:6:p1', 'GT:balagha_bayan:tashbih', 'bayan', 'Ibn ʿĀshūr: «kadhālika» is a simile. Either the likened is its own verbal noun — the coming-due reached such a pitch that only itself could be its likeness — or it is likened to the seizing of Nūḥ''s people and the factions (40:5), and then the simile compares two different things.', 'Grounded: QR:EV:40:6:ibn_ashur:1 and :2.', '{"ar": "تشبيه بالكاف: المشبه به إما المصدر نفسه فيفيد أن المشبه بلغ الغاية حتى لا يُشبَّه إلا بنفسه، وإما الأخذ المذكور في «فأخذتهم» (ابن عاشور).", "en": "A simile with the kāf: the likeness is either the coming-due itself — it reached such a pitch it could only be likened to itself — or the seizing in «so I seized them» (Ibn ʿĀshūr).", "ur": "کاف کے ذریعے تشبیہ: مشبہ بہ یا تو خود مصدر ہے — یعنی یہ ثبوت اس انتہا کو پہنچا کہ اسی سے تشبیہ دی جا سکے — یا «فاخذتہم» کی پکڑ (ابن عاشور)۔"}', '2026-10-15 16:00:00'),
('QR:BL:40:6:b2', 'sentence', 'QR:SS:40:6:jadwal:s1', 'GT:balagha_maani:itnab_tadhyil', 'mani', 'Ibn ʿĀshūr: if «those who disbelieved» means all disbelievers, the verse generalises after the particular nations of 40:5 — a closing summary (tadhyīl). If it means Quraysh (al-Zamakhsharī, al-Ālūsī, al-Ṭabarī, al-Rāzī), it is a threat aimed at the present opponents.', 'Conditional on the referent: see QR:NU:40:6:n1. Grounded: QR:EV:40:6:ibn_ashur:2.', '{"ar": "تذييل: تعميم بعد تخصيص إن أريد بـ«الذين كفروا» جميع الكافرين (ابن عاشور)؛ وإن أريد قريش فهو وعيد للحاضرين.", "en": "A closing summary: the general after the particular, if «those who disbelieved» are all disbelievers (Ibn ʿĀshūr); if Quraysh are meant, it is a threat to those present.", "ur": "تذییل: خاص کے بعد عام، اگر «الذین کفروا» سے تمام کافر مراد ہوں (ابن عاشور)؛ اور اگر قریش مراد ہوں تو موجودہ مخالفین کے لیے وعید ہے۔"}', '2026-10-15 16:00:00'),
('QR:BLK:QR:SS:40:6:jadwal:s1', 'sentence', 'QR:SS:40:6:jadwal:s1', 'GT:kalam_kind:khabar_ibtidai', 'mani', 'A plain assertion (khabar ibtidāʾī): the main clause carries no emphasizer — «anna» belongs to the content of the substitute, not to the assertion — and it is addressed to the Prophet through «your Lord», who does not deny it; it is told to console him (Ibn Kathīr: «consoling His Prophet»). A listener with no prior view needs no emphasis (al-Qazwīnī, al-Īḍāḥ 1/69).', 'Emphasizers on the main assertion: none. Addressee per the tafsīr: the Prophet, consoled (Ibn Kathīr; al-Ālūsī on «rabbika»). Rule: qazwini_idah 1/69.', '{"ar": "خبر ابتدائي: لا مؤكد في الجملة الرئيسة («أنّ» في مضمون البدل)، والمخاطب النبي ﷺ بـ«ربك» تسليةً له (ابن كثير)، وخالي الذهن يُستغنى معه عن المؤكدات (الإيضاح ١/٦٩).", "en": "A plain assertion: no emphasizer on the main clause («anna» lies inside the substitute), addressed to the Prophet through «your Lord» to console him (Ibn Kathīr); an open mind needs no emphasis (al-Īḍāḥ 1/69).", "ur": "خبرِ ابتدائی: مرکزی جملے میں کوئی مؤکد نہیں («انّ» بدل کے مضمون میں ہے)، اور مخاطب نبی ﷺ ہیں «ربک» کے ذریعے، تسلی کے لیے (ابن کثیر)؛ خالی الذہن کو تاکید کی حاجت نہیں (الایضاح ۱/۶۹)۔"}', '2026-10-15 16:00:00'),
('QR:BL:40:6:b3', 'phrase', 'QR:PH:40:6:p1', 'GT:balagha_maani:ijaz_hadhf', 'mani', 'The cognate object is left unsaid (ḥaqqan): «kadhālika» alone carries both the measure and the likeness, so the verse moves straight from the ruined nations to the present disbelievers.', 'Inferred from the iʿrāb books'' taqdīr (al-Jadwal, al-Daʿʿās, al-Muyassar); no tafsīr names the concision itself.', '{"ar": "إيجاز بالحذف: حُذف المصدر «حقًّا» واكتُفي بصفته «كذلك» (تقدير الجدول ودعاس والميسر).", "en": "Concision by omission: the verbal noun «ḥaqqan» is dropped and its qualifier «kadhālika» stands for it (the iʿrāb books'' taqdīr).", "ur": "حذف سے ایجاز: مصدر «حقاً» محذوف ہے اور اس کی صفت «کذلک» کافی ہے (الجدول، دعاس اور المیسر کی تقدیر)۔"}', '2026-10-15 16:00:00');

INSERT OR REPLACE INTO qr_ss_scope_nuance (id, scope_type, scope_id, nuance_type, nuance_text, nuance_text_ar, gloss_json, source_basis, source_ref, created_at, updated_at) VALUES
('QR:NU:40:6:n1', 'sentence', 'QR:SS:40:6:jadwal:s1', 'referent', 'Who are «those who disbelieved»? Quraysh, the present opponents (al-Zamakhsharī, al-Ālūsī, al-Ṭabarī, al-Rāzī: «of your people»), or every disbeliever, earlier and later (Ibn ʿAṭiyya; Ibn ʿĀshūr''s first reading).', 'من «الذين كفروا»؟ قريش المعاصرون (الزمخشري والألوسي والطبري والرازي: «من قومك»)، أو جميع الكفار من تقدم منهم ومن تأخر (ابن عطية، وابن عاشور في وجهه الأول).', '{"ar": "من «الذين كفروا»؟ قريش المعاصرون (الزمخشري والألوسي والطبري والرازي: «من قومك»)، أو جميع الكفار من تقدم منهم ومن تأخر (ابن عطية، وابن عاشور في وجهه الأول).", "en": "Who are «those who disbelieved»? Quraysh, the present opponents (al-Zamakhsharī, al-Ālūsī, al-Ṭabarī, al-Rāzī: «of your people»), or every disbeliever, earlier and later (Ibn ʿAṭiyya; Ibn ʿĀshūr''s first reading).", "ur": "«الذین کفروا» کون ہیں؟ قریش، یعنی موجودہ مخالفین (زمخشری، آلوسی، طبری، رازی: «تیری قوم میں سے»)، یا تمام کافر، اگلے پچھلے (ابن عطیہ؛ ابن عاشور کا پہلا قول)۔"}', 'tafsir', 'zamakhshari;alusi;tabari;razi;ibn_atiyya;ibn_ashur', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:NU:40:6:n2', 'sentence', 'QR:SS:40:6:jadwal:s1', 'lexical', '«kalima» is God''s word of threat to the deniers, His sealed decree (Ibn ʿĀshūr: His sayings revealed to the messengers threatening the deniers; Ibn ʿAṭiyya: the sealing of the decree upon them). Nāfiʿ, Ibn ʿĀmir and Abū Jaʿfar read «kalimāt»; the singular is a genus and means the same (Ibn ʿĀshūr).', '«كلمة ربك» وعيده للمكذبين وقضاؤه المختوم عليهم (ابن عاشور، ابن عطية). وقرأ نافع وابن عامر وأبو جعفر «كلمات»، والإفراد للجنس فهو مساوٍ للجمع (ابن عاشور).', '{"ar": "«كلمة ربك» وعيده للمكذبين وقضاؤه المختوم عليهم (ابن عاشور، ابن عطية). وقرأ نافع وابن عامر وأبو جعفر «كلمات»، والإفراد للجنس فهو مساوٍ للجمع (ابن عاشور).", "en": "«kalima» is God''s word of threat to the deniers, His sealed decree (Ibn ʿĀshūr: His sayings revealed to the messengers threatening the deniers; Ibn ʿAṭiyya: the sealing of the decree upon them). Nāfiʿ, Ibn ʿĀmir and Abū Jaʿfar read «kalimāt»; the singular is a genus and means the same (Ibn ʿĀshūr).", "ur": "«کلمۃ ربک» جھٹلانے والوں کے لیے اس کی وعید اور ان پر مہر شدہ فیصلہ ہے (ابن عاشور، ابن عطیہ)۔ نافع، ابن عامر اور ابو جعفر نے «کلمات» پڑھا؛ مفرد جنس کے لیے ہے، اس لیے جمع کے برابر ہے (ابن عاشور)۔"}', 'tafsir', 'ibn_ashur;ibn_atiyya', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:NU:40:6:n3', 'sentence', 'QR:SS:40:6:jadwal:s1', 'aspect', 'The perfect «ḥaqqat» states as settled what is still to fall: they stand «on the verge of its coming down on them» (al-Rāzī). Al-Ālūsī: as destruction came due on the factions in this world, the Fire comes due on these in the next.', 'الماضي «حقّت» يقرّر واقعًا ما لم يقع بعد: «فهم على شرف نزول العقاب بهم» (الرازي). والألوسي: كما وجب إهلاك أولئك في الدنيا وجب على هؤلاء عذاب النار في الآخرة.', '{"ar": "الماضي «حقّت» يقرّر واقعًا ما لم يقع بعد: «فهم على شرف نزول العقاب بهم» (الرازي). والألوسي: كما وجب إهلاك أولئك في الدنيا وجب على هؤلاء عذاب النار في الآخرة.", "en": "The perfect «ḥaqqat» states as settled what is still to fall: they stand «on the verge of its coming down on them» (al-Rāzī). Al-Ālūsī: as destruction came due on the factions in this world, the Fire comes due on these in the next.", "ur": "ماضی «حقت» ابھی آنے والی چیز کو طے شدہ بیان کرتا ہے: «وہ عذاب کے نازل ہونے کے کنارے پر ہیں» (رازی)۔ آلوسی: جیسے ان قوموں پر دنیا میں ہلاکت واجب ہوئی، ویسے ہی ان پر آخرت میں آگ۔"}', 'tafsir', 'razi;alusi;zamakhshari', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:NU:40:6:n4', 'sentence', 'QR:SS:40:6:jadwal:s1', 'addressee', '«your Lord» — the title of lordship joined to the Prophet''s own pronoun (al-Ālūsī): the verse consoles him, that he has the example of the messengers before him (Ibn Kathīr).', '«ربك»: التعبير بعنوان الربوبية مع الإضافة إلى ضميره ﷺ (الألوسي)، تسليةً له بأن له أسوة بمن سلف من الأنبياء (ابن كثير).', '{"ar": "«ربك»: التعبير بعنوان الربوبية مع الإضافة إلى ضميره ﷺ (الألوسي)، تسليةً له بأن له أسوة بمن سلف من الأنبياء (ابن كثير).", "en": "«your Lord» — the title of lordship joined to the Prophet''s own pronoun (al-Ālūsī): the verse consoles him, that he has the example of the messengers before him (Ibn Kathīr).", "ur": "«ربک»: ربوبیت کا عنوان نبی ﷺ کی ضمیر کی طرف اضافت کے ساتھ (آلوسی)، ان کی تسلی کے لیے کہ ان سے پہلے انبیاء کا اسوہ ان کے سامنے ہے (ابن کثیر)۔"}', 'tafsir', 'alusi;ibn_kathir', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:NU:40:6:n5', 'sentence', 'QR:SS:40:6:jadwal:s1', 'word_choice', '«aṣḥāb an-nār» stands in place of all their traits because it is the last and worst of them and implies the rest (al-Ālūsī); «aṣḥāb» are its people and dwellers (Ibn ʿAṭiyya).', '«أصحاب النار» وُضع موضع أوصافهم لأنه آخرها وشرّها والدالّ على الباقي (الألوسي)؛ وأصحابها أهلها وسكانها (ابن عطية).', '{"ar": "«أصحاب النار» وُضع موضع أوصافهم لأنه آخرها وشرّها والدالّ على الباقي (الألوسي)؛ وأصحابها أهلها وسكانها (ابن عطية).", "en": "«aṣḥāb an-nār» stands in place of all their traits because it is the last and worst of them and implies the rest (al-Ālūsī); «aṣḥāb» are its people and dwellers (Ibn ʿAṭiyya).", "ur": "«اصحاب النار» ان کے تمام اوصاف کی جگہ رکھا گیا کیونکہ یہ آخری اور بدترین وصف ہے اور باقی پر دلالت کرتا ہے (آلوسی)؛ اصحاب یعنی اس کے رہنے والے (ابن عطیہ)۔"}', 'tafsir', 'alusi;ibn_atiyya', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:NU:40:6:n6', 'sentence', 'QR:SS:40:6:jadwal:s1', 'theology', 'Al-Rāzī reports the Ashʿarī argument from this verse that God''s decree of bliss and misery is binding and cannot change; Ibn ʿĀshūr reads it as conditional — the threat holds «if they do not desist» — and sees in it a hint that the Muḥammadan community will not be uprooted, since God meant to bring believers from among them.', 'احتج الأشاعرة بها على أن قضاء الله بالسعادة والشقاوة لازم لا يمكن تغييره (الرازي)؛ وابن عاشور يجعل الوعيد مشروطًا «إذا لم يقلعوا عن كفرهم»، ويرى فيها إيماءً إلى أن الله غير معاقب أمة الدعوة المحمدية بالاستئصال.', '{"ar": "احتج الأشاعرة بها على أن قضاء الله بالسعادة والشقاوة لازم لا يمكن تغييره (الرازي)؛ وابن عاشور يجعل الوعيد مشروطًا «إذا لم يقلعوا عن كفرهم»، ويرى فيها إيماءً إلى أن الله غير معاقب أمة الدعوة المحمدية بالاستئصال.", "en": "Al-Rāzī reports the Ashʿarī argument from this verse that God''s decree of bliss and misery is binding and cannot change; Ibn ʿĀshūr reads it as conditional — the threat holds «if they do not desist» — and sees in it a hint that the Muḥammadan community will not be uprooted, since God meant to bring believers from among them.", "ur": "رازی نقل کرتے ہیں کہ اشاعرہ نے اس آیت سے استدلال کیا کہ سعادت و شقاوت کا الٰہی فیصلہ لازم اور ناقابلِ تغیر ہے؛ ابن عاشور وعید کو مشروط بناتے ہیں «اگر وہ کفر سے باز نہ آئیں»، اور اس میں اشارہ دیکھتے ہیں کہ امتِ دعوت کو جڑ سے نہیں اکھاڑا جائے گا۔"}', 'tafsir', 'razi;ibn_ashur', '2026-10-15 16:00:00', '2026-10-15 16:00:00'),
('QR:NU:40:6:n7', 'sentence', 'QR:SS:40:6:jadwal:s1', 'reading', 'The muṣḥaf of ʿAbdallāh ibn Masʿūd has «kadhālika sabaqat» — explained as a gloss of meaning, not a reading (al-Ālūsī; Ibn ʿAṭiyya reports it).', 'وفي مصحف عبد الله بن مسعود «وكذلك سبقت»، وهو على ما قيل تفسير معنى لا قراءة (الألوسي؛ ونقله ابن عطية).', '{"ar": "وفي مصحف عبد الله بن مسعود «وكذلك سبقت»، وهو على ما قيل تفسير معنى لا قراءة (الألوسي؛ ونقله ابن عطية).", "en": "The muṣḥaf of ʿAbdallāh ibn Masʿūd has «kadhālika sabaqat» — explained as a gloss of meaning, not a reading (al-Ālūsī; Ibn ʿAṭiyya reports it).", "ur": "عبد اللہ بن مسعودؓ کے مصحف میں «وکذلک سبقت» ہے، جسے قراءت نہیں بلکہ معنی کی تفسیر کہا گیا ہے (آلوسی؛ ابن عطیہ نے نقل کیا)۔"}', 'tafsir', 'alusi;ibn_atiyya', '2026-10-15 16:00:00', '2026-10-15 16:00:00');

INSERT OR REPLACE INTO qr_ss_ellipsis_event (id, sentence_id, scope_type, scope_id, ellipsis_type, lx_ellipsis_ref, elided_element, rhetorical_effect, note_md, source_basis, source_ref, created_at) VALUES
('QR:EL:40:6:masdar', 'QR:SS:40:6:jadwal:s1', 'phrase', 'QR:PH:40:6:p1', 'masdar_mahdhuf', 'GT:balagha_maani:ijaz_hadhf', 'حَقًّا', 'The cognate object is understood: «came due with a coming-due like that».', 'تقدير الجدول ودعاس والميسر: حقّت حقًّا مثلَ ذلك.', 'irab', 'qul_jadwal_irab_quran;qul_irab_quran_daas;qul_irab_muyassar', '2026-10-15 16:00:00'),
('QR:EL:40:6:lam', 'QR:SS:40:6:jadwal:s1', 'phrase', 'QR:PH:40:6:p4', 'harf_jarr_mahdhuf', 'GT:irab_role:nazu_khafid', 'لِـ (لام التعليل)', 'On the minority reading the cause is given without its particle: «because they are the people of the Fire».', 'الألوسي والزمخشري وابن عاشور والميسر؛ وحذف الجار قبل أنّ مطّرد (مغني اللبيب ص١٥).', 'tafsir;irab', 'alusi;zamakhshari;ibn_ashur;qul_irab_muyassar', '2026-10-15 16:00:00');

INSERT OR REPLACE INTO qr_ss_discourse_note (id, scope_type, scope_id, surah, marker, question_ar, verdict_ar, source_basis, status, created_at) VALUES
('QR:DN:40:6a', 'phrase', 'QR:PH:40:6:p4', 40, '¹', 'ما محلّ «أنّهم أصحاب النار» من الإعراب؟', 'المرجّح: بدل مرفوع من «كلمة ربك» (دعاس والميسر والزمخشري وابن عطية والطبري وابن عاشور)؛ والألوسي يرجّح النصب بنزع الخافض «لأنّهم» بالمساق.', 'irab;tafsir', 'raw', '2026-10-15 16:00:00'),
('QR:DN:40:6b', 'sentence', 'QR:SS:40:6:jadwal:s1', 40, '²', 'من المراد بـ«الذين كفروا»؟', 'قريش عند الزمخشري والألوسي والطبري والرازي؛ وجميع الكفار عند ابن عطية وابن عاشور في وجهه الأول.', 'tafsir', 'raw', '2026-10-15 16:00:00');

