INSERT OR REPLACE INTO qr_ss_scope_link (id, from_scope_type, from_scope_id, to_scope_type, to_scope_id, relation_type, note_md, source_basis, gloss_json, created_at) VALUES
('QR:SREL:40:6:1', 'sentence', 'QR:SS:40:6:jadwal:s1', 'sentence', 'QR:SS:40:5:s5', 'istinaf_aw_atf', 'استئناف (الجدول ودعاس) أو عطف على «فكيف كان عقاب» (ابن عاشور).', 'qul_jadwal_irab_quran;qul_irab_quran_daas;ibn_ashur', '{"ar": "استئناف بعد «فكيف كان عقاب» (الجدول ودعاس)، أو عطف عليها (ابن عاشور).", "en": "Resumes after «so how was My punishment?» (al-Jadwal, al-Daʿʿās), or is joined to it (Ibn ʿĀshūr).", "ur": "«فکیف کان عقاب» کے بعد استیناف (الجدول، دعاس)، یا اس پر عطف (ابن عاشور)۔"}', '2026-10-15 16:00:00'),
('QR:SREL:40:6:2', 'sentence', 'QR:SS:40:6:jadwal:s1', 'sentence', 'QR:SS:40:5:s4', 'tashbih', 'المشبه به: الأخذ في «فأخذتهم» (ابن عاشور وجهًا)؛ وكما حقّ العقاب على الأمم السالفة (الطبري والرازي والألوسي).', 'ibn_ashur;tabari;razi;alusi', '{"ar": "«كذلك»: كما حقّ الأخذ على الأمم في «فأخذتهم» حقّت الكلمة على هؤلاء.", "en": "«Just so»: as the seizing in «so I seized them» came due on those nations, the word came due on these.", "ur": "«کذلک»: جیسے «فاخذتہم» میں ان قوموں پر پکڑ واقع ہوئی، ویسے ہی ان پر کلمہ ثابت ہوا۔"}', '2026-10-15 16:00:00'),
('QR:SREL:40:6:3', 'sentence', 'QR:SS:40:6:jadwal:s1', 'sentence', 'QR:SS:40:4:s1', 'same_referent', '«الذين كفروا» هم المذكورون في «ما يجادل في آيات الله إلا الذين كفروا» (ابن عاشور وجهًا، والطبري: الذين يجادلون في آيات الله).', 'ibn_ashur;tabari', '{"ar": "«الذين كفروا» هنا هم المجادلون في آيات الله في الآية الرابعة (ابن عاشور وجهًا، والطبري).", "en": "«Those who disbelieved» are the ones who dispute God''s signs in 40:4 (one reading of Ibn ʿĀshūr; al-Ṭabarī).", "ur": "یہاں «الذین کفروا» وہی ہیں جو آیت ۴ میں اللہ کی آیات میں جھگڑتے ہیں (ابن عاشور کا ایک قول؛ طبری)۔"}', '2026-10-15 16:00:00');

INSERT OR REPLACE INTO qr_ss_translation_unit (id, scope_type, scope_id, surah, ayah_from, ayah_to, seq, structural_literal_en, fluent_en, fluent_ar, decision_note_ar, synthesis_md, gloss_json, status, reading_ref, rejected_readings_json, created_at, updated_at) VALUES
('QR:TL:40:6:jadwal:s1', 'sentence', 'QR:SS:40:6:jadwal:s1', 40, 6, 6, 1, 'And like that, the word of your Lord came due upon those who disbelieved — that they are the companions of the Fire.', 'Just so has your Lord''s word come due against those who disbelieve: they are the people of the Fire.', 'وكما حقّ العقاب على الأمم الماضية، حقّت كلمة ربك على الذين كفروا: أنّهم أهل النار.', 'الترجمة على قول الجمهور (البدل)، والنقطتان تحملان البدل؛ وقول التعليل محفوظ في المرفوضات.', 'Rendered on the majority reading: «that they are the people of the Fire» substitutes for «your Lord''s word», so the colon introduces what the word says. What English loses: (1) the cognate object elided under «kadhālika» — «Just so» carries the likeness, not the verbal noun; (2) al-Ālūsī''s reading «because they are the people of the Fire», which the colon cannot hold at the same time; (3) the perfect «ḥaqqat» stating as settled what has yet to fall — «has come due» keeps the settledness but not al-Rāzī''s «on the verge»; (4) whether «those who disbelieve» are Quraysh or every disbeliever, which the English leaves open, as the commentators do.', '{"ar": "ترجمة على قول البدل؛ وتفوت الإنجليزيةَ المصدرُ المحذوف، ووجهُ التعليل، ودلالةُ الماضي على المستقبل المحقَّق، وتعيينُ «الذين كفروا».", "en": "Rendered on the substitute reading; English loses the elided verbal noun, the causal reading, the perfect for a settled future, and who «those who disbelieve» are.", "ur": "بدل والے قول پر ترجمہ؛ انگریزی میں محذوف مصدر، تعلیل والا قول، ماضی سے یقینی مستقبل کی دلالت، اور «الذین کفروا» کی تعیین فوت ہو جاتی ہے۔"}', 'live', 'QR:SR:40:6:r5', '[{"reading_ref": "QR:SR:40:6:r6", "en": "Just so has your Lord''s word come due against those who disbelieve, because they are the people of the Fire.", "why": "Al-Ālūsī''s preference, but the minority; the colon of the substitute reading is kept, and this rendering recorded."}]', '2026-10-15 16:00:00', '2026-10-15 16:00:00');

INSERT OR REPLACE INTO qr_ss_translation_decision (id, unit_id, surah, ayah, step_seq, target_span_ar, rendered_json, driver_kind, driver_ref, rationale_json, status, created_at) VALUES
('QR:TD:40:6:d1', 'QR:TL:40:6:jadwal:s1', 40, 6, 1, 'وَكَذَلِكَ', '{"ar": "وكما حقّ على أولئك", "en": "Just so", "ur": "اسی طرح"}', 'grammar', 'GT:irab_role:maful_mutlaq', '{"ar": "الكاف صفة لمصدر محذوف، والتشبيه بالمذكور قبلها؛ «Just so» يحمل المماثلة دون المصدر.", "en": "The kāf qualifies an elided cognate object and likens to what precedes; «Just so» carries the likeness without the verbal noun."}', 'live', '2026-10-15 16:00:00'),
('QR:TD:40:6:d2', 'QR:TL:40:6:jadwal:s1', 40, 6, 2, 'حَقَّتْ … عَلَى', '{"ar": "حقّت على", "en": "has come due against", "ur": "ثابت ہو چکا ہے ان پر"}', 'nuance', 'QR:NU:40:6:n3', '{"ar": "الماضي يقرّر ما سيقع، و«على» للإلزام؛ «has come due against» يحفظ الثبوت والإلزام.", "en": "The perfect settles what will fall, and «ʿalā» binds it against them; «has come due against» keeps both."}', 'live', '2026-10-15 16:00:00'),
('QR:TD:40:6:d3', 'QR:TL:40:6:jadwal:s1', 40, 6, 3, 'كَلِمَتُ رَبِّكَ', '{"ar": "كلمة ربك", "en": "your Lord''s word", "ur": "تیرے رب کی بات"}', 'nuance', 'QR:NU:40:6:n4', '{"ar": "الإضافة إلى ضمير النبي ﷺ تسلية له، فتبقى «your Lord» لا «God».", "en": "The annexation to the Prophet''s pronoun consoles him, so «your Lord» stays, not «God»."}', 'live', '2026-10-15 16:00:00'),
('QR:TD:40:6:d4', 'QR:TL:40:6:jadwal:s1', 40, 6, 4, 'الَّذِينَ كَفَرُوا', '{"ar": "الذين كفروا", "en": "those who disbelieve", "ur": "جنہوں نے کفر کیا"}', 'nuance', 'QR:NU:40:6:n1', '{"ar": "المراد مختلف فيه (قريش أو جميع الكفار)، فتُترك العبارة مفتوحة بصيغة الحاضر.", "en": "The referent is disputed (Quraysh or all disbelievers), so the phrase is left open, in the present."}', 'live', '2026-10-15 16:00:00'),
('QR:TD:40:6:d5', 'QR:TL:40:6:jadwal:s1', 40, 6, 5, 'أَنَّهُمْ', '{"ar": "أنّهم (بدل)", "en": ": they are", "ur": ": کہ وہ"}', 'reading', 'QR:SR:40:6:r5', '{"ar": "على البدل تكون الجملة مضمونَ الكلمة، فتُقدَّم بنقطتين لا بـ because.", "en": "On the substitute reading the clause is the content of the word, so it follows a colon, not «because»."}', 'live', '2026-10-15 16:00:00'),
('QR:TD:40:6:d6', 'QR:TL:40:6:jadwal:s1', 40, 6, 6, 'أَصْحَابُ النَّارِ', '{"ar": "أهل النار", "en": "the people of the Fire", "ur": "اہلِ دوزخ"}', 'nuance', 'QR:NU:40:6:n5', '{"ar": "الأصحاب أهلها وسكانها (ابن عطية)، فـ people لا companions في الترجمة الفصيحة.", "en": "«aṣḥāb» are its people and dwellers (Ibn ʿAṭiyya), so «people», not «companions», in the fluent rendering."}', 'live', '2026-10-15 16:00:00');

